(function(){
const previousOpenPanel=openPanel;openPanel=async function(s){await previousOpenPanel(s);if(adminState.session)loadCustomers()};
const heading=document.querySelector('.admin-heading');if(!heading)return;heading.insertAdjacentHTML('beforeend','<button id="admin-customers-toggle" class="secondary" type="button">Clientes</button>');document.querySelector('#admin-panel').insertAdjacentHTML('beforeend','<section id="admin-customers" class="admin-orders" hidden><h2>Clientes cadastrados</h2><div id="admin-customer-list"></div></section>');
async function loadCustomers(){const list=document.querySelector('#admin-customer-list');try{const rows=await request('/rest/v1/profiles?select=id,full_name,email,phone,birth_date,default_address,created_at&role=eq.customer&order=created_at.desc');list.innerHTML=rows.length?rows.map(c=>`<article class="order-card"><strong>${escapeHtml(c.full_name||'Cliente sem nome')}</strong><span>${escapeHtml(c.email||'E-mail não informado')}</span><small>${c.phone?escapeHtml(c.phone)+' · ':''}Cadastro: ${new Date(c.created_at).toLocaleDateString('pt-BR')}</small><p>${escapeHtml(c.default_address?([c.default_address.street,c.default_address.number,c.default_address.neighborhood,c.default_address.reference?'Ref.: '+c.default_address.reference:''].filter(Boolean).join(', ')||'Sem endereço cadastrado'):'Sem endereço cadastrado')}</p></article>`).join(''):'<p>Nenhum cliente cadastrado.</p>'}catch(e){list.innerHTML='<p>'+escapeHtml(e.message)+'</p>'}}
document.querySelector('#admin-customers-toggle').onclick=()=>{const x=document.querySelector('#admin-customers');x.hidden=!x.hidden;if(!x.hidden)loadCustomers()};
})();